var t=`0051-gulas`;var n=`world-0051`;var a=`CZ`;var s=`eastern-europe`;var o=4;var r=127;var l={en:`Guláš`,ua:`Чеський гуляш`};var d={en:`A classic dish from Czechia, featuring beef chuck, yellow onion, garlic. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Чехія. Основні складники: яловича лопатка, жовта цибуля, часник. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,700,`g`],[`lard`,45,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,300,`g`],[`sweet-paprika`,20,`g`],[`garlic`,3,`clove`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 100 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 100 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:100,i:[[`beef-stock`,600,`ml`],[`caraway-seeds`,4,`g`],[`dried-marjoram`,4,`g`],[`tomato-paste`,40,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var u={slug:t,id:n,country:`CZ`,region:s,servings:4,minutes:127,title:l,text:d,steps:g};export{a as country,u as default,n as id,r as minutes,s as region,o as servings,t as slug,g as steps,d as text,l as title};